module coin_game (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [6:0] n,\n    input wire [9:0] a [0:99],\n    output reg signed [19:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] COPY   = 3'd1;\n    localparam [2:0] COMP   = 3'd2;\n    localparam [2:0] FINISH = 3'd3;\n    localparam [2:0] ERROR  = 3'd4;\n    \n    reg [2:0] state;\n    reg signed [15:0] mem [0:99];\n    reg [6:0] x;\n    reg signed [19:0] total_moves;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 20'sd0;\n            total_moves <= 20'sd0;\n            x <= 7'd0;\n            for (i = 0; i < 100; i = i + 1) begin\n                mem[i] <= 16'sd0;\n            end\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        if (n == 7'd1 || n[0] == 1'b0) begin\n                            state <= ERROR;\n                        end else begin\n                            state <= COPY;\n                            x <= (n >> 1);\n                            total_moves <= 20'sd0;\n                        end\n                    end\n                end\n                \n                COPY: begin\n                    for (i = 0; i < 100; i = i + 1) begin\n                        if (i < n) mem[i] <= a[i];\n                        else mem[i] <= 16'sd0;\n                    end\n                    state <= COMP;\n                end\n                \n                COMP: begin\n                    if (x >= 7'd1) begin\n                        if ((7'd2 * x) <= n && (7'd2 * x + 7'd1) <= n) begin\n                            if (mem[7'd2 * x - 7'd1] > mem[7'd2 * x]) begin\n                                total_moves <= total_moves + mem[7'd2 * x - 7'd1];\n                                mem[x - 7'd1] <= mem[x - 7'd1] - mem[7'd2 * x - 7'd1];\n                            end else begin\n                                total_moves <= total_moves + mem[7'd2 * x];\n                                mem[x - 7'd1] <= mem[x - 7'd1] - mem[7'd2 * x];\n                            end\n                        end\n                        x <= x - 7'd1;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    result <= (mem[7'd0] > 16'sd0) ? (total_moves + mem[7'd0]) : total_moves;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                ERROR: begin\n                    result <= -20'sd1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule